-- Ejecutar una sola vez en Supabase (Dashboard → SQL Editor → New query → Run).
-- Crea las tablas de Flashcards (repetición espaciada estilo Anki) y carga
-- el mazo "Mi baraja" (271 tarjetas) que sustituye a la pestaña "Curiosidades".

create table if not exists public.flashcards (
  id uuid primary key default gen_random_uuid(),
  mazo text not null,
  frontal text not null,
  posterior text not null,
  created_at timestamptz not null default now()
);

alter table public.flashcards enable row level security;
drop policy if exists "flashcards_select" on public.flashcards;
create policy "flashcards_select" on public.flashcards for select using (true);
drop policy if exists "flashcards_insert" on public.flashcards;
create policy "flashcards_insert" on public.flashcards for insert with check (true);

-- Progreso de repaso por persona y tarjeta (algoritmo SM-2, como Anki):
-- ease_factor = "facilidad" de la tarjeta (empieza en 2.5, sube o baja según
-- lo fácil/difícil que la marque la persona cada vez); intervalo_dias = cada
-- cuántos días toca repasarla; proxima_revision = próxima fecha en la que
-- volverá a aparecer como pendiente.
create table if not exists public.flashcards_progreso (
  name text not null,
  flashcard_id uuid not null references public.flashcards(id) on delete cascade,
  ease_factor numeric not null default 2.5,
  intervalo_dias integer not null default 0,
  repeticiones integer not null default 0,
  proxima_revision date,
  ultima_revision timestamptz,
  updated_at timestamptz not null default now(),
  primary key (name, flashcard_id)
);

alter table public.flashcards_progreso enable row level security;
drop policy if exists "flashcards_progreso_select" on public.flashcards_progreso;
create policy "flashcards_progreso_select" on public.flashcards_progreso for select using (true);
drop policy if exists "flashcards_progreso_insert" on public.flashcards_progreso;
create policy "flashcards_progreso_insert" on public.flashcards_progreso for insert with check (true);
drop policy if exists "flashcards_progreso_update" on public.flashcards_progreso;
create policy "flashcards_progreso_update" on public.flashcards_progreso for update using (true) with check (true);

